class ErrorBoundary extends React.Component {
  state = { error: null, key: 0 };

  static getDerivedStateFromError(error) {
    return { error };                        // render fallback on next pass
  }

  componentDidCatch(error, info) {
    // Log where it happened — componentStack tells you the subtree path
    errorReporter.captureException(error, {
      extra: { componentStack: info.componentStack },
    });
  }

  retry = () => this.setState((s) => ({ error: null, key: s.key + 1 }));

  render() {
    if (this.state.error) {
      return this.props.fallback?.(this.state.error, this.retry) ?? (
        <div role="alert">
          <p>Something went wrong in this section.</p>
          <button onClick={this.retry}>Try again</button>
        </div>
      );
    }
    return <React.Fragment key={this.state.key}>{this.props.children}</React.Fragment>;
  }
}

// Usage: nest by blast radius — widget inside feature inside app shell
<ErrorBoundary>                                   {/* app shell: reload */}
  <Header />
  <ErrorBoundary fallback={(err, retry) => <DashboardFallback retry={retry} />}>
    <Dashboard />                                 {/* feature: inline recovery */}
  </ErrorBoundary>
  <ErrorBoundary>
    <RecommendationsWidget />                     {/* widget: degrade alone */}
  </ErrorBoundary>
</ErrorBoundary>

// What boundaries do NOT catch — handle locally:
async function onDelete() {
  try {
    await api.delete(id);                         // rejected promise escapes boundaries
  } catch (error) {
    setBanner({ tone: 'error', text: 'Delete failed — try again.' });
  }
}

// Event handlers never bubble to boundaries:
<button onClick={() => { try { risky(); } catch (e) { toast.error('Failed'); } }}>
  Run
</button>
